#ifndef CUENTA_H
#define CUENTA_H

typedef enum {
  OK,
  SALDO_INSUFICIENTE
} TResultado;

typedef struct {
  int numero;
  double saldo;
} TCuenta;

TCuenta crear(int numero);
void depositar(TCuenta *c, double monto);
TResultado retirar(TCuenta *c, double monto);
double obtenerSaldo(TCuenta c);
int obtenerNumero(TCuenta c);

#endif

#include "cuenta.h"

TCuenta crear(int numero) {
  TCuenta c;

  c.numero = numero;
  c.saldo = 0;
  return c;
}

void depositar(TCuenta *c, double monto) {
  c->saldo = c->saldo + monto;
}

TResultado retirar(TCuenta *c, double monto) {
  if (monto > c->saldo) {
    return SALDO_INSUFICIENTE;
  }
  c->saldo = c->saldo - monto;
  return OK;
}

double obtenerSaldo(TCuenta c) {
  return c.saldo;
}

int obtenerNumero(TCuenta c) {
  return c.numero;
}

