#include "cuenta.h"

#define MAX 10

int main() {
  TCuenta cuentas[MAX];
  double saldo;
  double cuota;
  int numero;
  int cobradas = 0;
  int n;

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &numero);
    scanf("%lf", &saldo);
    cuentas[i] = crear(numero);
    depositar(&cuentas[i], saldo);
  }
  scanf("%lf", &cuota);
  for (int i = 0; i < n; i++) {
    if (retirar(&cuentas[i], cuota) == OK) {
      cobradas++;
    } else {
      printf("Cuenta %d no pudo pagar\n", obtenerNumero(cuentas[i]));
    }
  }
  printf("Cobradas: %d", cobradas);
  return 0;
}

